WITH expected(name,body_hash) AS (VALUES ('tm_can_read_journey_patient','8d695c846054255b87914f6341459fac'),('tm_submit_journey_self_report','a884ca02695ce5207c2fe6da8e4763e2'),('tm_set_journey_preference','1e0859f5eb93285dd2b46678f6be9664'),('tm_get_journey_preference','62f4d6c0692594dfa81c8f989c4836b7'),('tm_pause_journey_goal','796d901c9565e50da2bdffb633b204a0'),('tm_get_journey_goal_for_doctor','49ec2e52318725fb5f972e27adfc904f'),('tm_submit_journey_self_report_for_clinic','330e2675f944669a11e7825d7b82e9cf')) SELECT jsonb_build_object('tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'anon_select',has_table_privilege('anon',c.oid,'SELECT'),'authenticated_write',has_table_privilege('authenticated',c.oid,'INSERT,UPDATE,DELETE'),'authenticated_select',has_table_privilege('authenticated',c.oid,'SELECT'))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('tm_journey_goals','tm_journey_preferences','tm_journey_events','tm_journey_preference_audit','tm_journey_goal_audit')),'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'signature',p.oid::regprocedure::text,'source_matches',md5(regexp_replace(p.prosrc,E'\n{2,}',E'\n','g'))=e.body_hash,'security_definer',p.prosecdef,'config',p.proconfig,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'))) FROM expected e JOIN pg_proc p ON p.proname=e.name JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'),'counts',jsonb_build_object('goals',(SELECT count(*) FROM public.tm_journey_goals),'preferences',(SELECT count(*) FROM public.tm_journey_preferences),'events',(SELECT count(*) FROM public.tm_journey_events),'preference_audit',(SELECT count(*) FROM public.tm_journey_preference_audit),'goal_audit',(SELECT count(*) FROM public.tm_journey_goal_audit),'patients',(SELECT count(*) FROM public.tm_patients),'memberships',(SELECT count(*) FROM public.tm_memberships),'grants',(SELECT count(*) FROM public.tm_membership_grants)),'resources',(SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conname='tm_membership_grants_resource_check')) AS verification;